# Settings-getter sites for the AF target keys, and whether a pose read is nearby.
# Read-only. Do not edit this file after it has run.
from pathlib import Path

BASE = 0x60021020
img = Path('inputs/00_0100_50000020.decoded.bin').read_bytes()
n = len(img)
GETTER = 0x60063380
KEYS = {
    0x99A1: '99a1', 0x5962: '5962', 0x9A41: '9a41', 0x1DD1: '1dd1',
    0x88B2: '88b2', 0x84D1: '84d1',
}
POSE_CALLS = {0x60077DE1: 'exif', 0x60077E01: 'raw'}


def s32(off):
    v = int.from_bytes(img[off:off + 4], 'little')
    return v - 0x100000000 if v & 0x80000000 else v


def s16(off):
    v = img[off] | (img[off + 1] << 8)
    return v - 0x10000 if v & 0x8000 else v


def call_target(off):
    op = img[off]
    pc = BASE + off
    if op == 0xDD and off + 7 <= n:
        return (pc + s32(off + 1)) & 0xFFFFFFFF, 7
    if op == 0xCD and off + 5 <= n:
        return (pc + s16(off + 1)) & 0xFFFFFFFF, 5
    return None, 0


sites = []
i = 0
while i < n - 7:
    target, length = call_target(i)
    if target != GETTER:
        i += 1
        continue
    pc = BASE + i
    window = img[max(0, i - 16):i]
    key = None
    key_at = None
    # 32-bit mov into D0: fc cc imm32
    for back in range(6, 17):
        j = i - back
        if j < 0:
            break
        if img[j] == 0xFC and img[j + 1] == 0xCC and j + 6 <= i:
            imm = int.from_bytes(img[j + 2:j + 6], 'little')
            if imm in KEYS:
                key = imm
                key_at = BASE + j
                break
        if img[j] == 0x2C and j + 3 <= i:
            imm = img[j + 1] | (img[j + 2] << 8)
            if imm in KEYS:
                key = imm
                key_at = BASE + j
                break
    if key is None:
        i += 1
        continue
    # D1 source in the 12 bytes before the call. The key mov is not always last.
    d1 = 'unknown'
    pre = img[max(0, i - 12):i]
    for k in range(len(pre) - 1, -1, -1):
        if pre[k] == 0x04 and k + 1 == len(pre):
            d1 = 'clr'
            break
        if pre[k] == 0x85 and k + 2 <= len(pre):
            d1 = f'imm8 {pre[k + 1]}'
            break
        if pre[k] == 0x2D and k + 3 <= len(pre):
            d1 = f'imm16 {pre[k + 1] | (pre[k + 2] << 8)}'
            break
        if pre[k] == 0xFC and k + 1 < len(pre) and pre[k + 1] == 0xCD and k + 6 <= len(pre):
            d1 = f"imm32 {int.from_bytes(pre[k + 2:k + 6], 'little')}"
            break
        if pre[k] in (0x81, 0x82, 0x83, 0x8D, 0x8E, 0x8F) and k + 1 == len(pre):
            d1 = f'reg {pre[k]:02x}'
            break
    # Pose read in the 96 bytes before the getter call.
    pose = None
    start = max(0, i - 96)
    for j in range(start, i):
        t, _ln = call_target(j)
        if t in POSE_CALLS:
            pose = f'{POSE_CALLS[t]} {BASE + j:08x}'
        if img[j] == 0xFC and j + 6 <= i:
            abs_addr = int.from_bytes(img[j + 2:j + 6], 'little')
            if abs_addr in (0xA32C568C, 0xA32C5690, 0xA32C5688, 0xA33AC4E2):
                pose = f'abs {abs_addr:08x} at {BASE + j:08x}'
    prehex = img[max(0, i - 12):i].hex()
    sites.append((pc, KEYS[key], key_at, d1, pose, prehex))
    i += length

lines = [f'scan-index-r1 sites {len(sites)}']
for pc, name, key_at, d1, pose, prehex in sites:
    lines.append(f'{pc:08x} key {name} mov {key_at:08x} d1 {d1} pose {pose or "-"} pre {prehex}')
text = '\n'.join(lines) + '\n'
Path('work/out/scan-index-r1.txt').write_text(text, encoding='utf-8')
print(text)
